use std::collections::HashMap;

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Find the last position (highest index) where `cafe` appears.
    // `rposition` scans from the end toward the front.
    cafes
        .iter()
        .rposition(|&x| x == cafe)
        .expect("cafe must appear in the array")
}

fn solve(cafes: Vec<i8>) -> i8 {
    // Build a map from each cafe value to its last occurrence index.
    let mut last_pos: HashMap<i8, usize> = HashMap::new();
    for (i, &c) in cafes.iter().enumerate() {
        last_pos.insert(c, i);
    }

    // Find the cafe whose last occurrence index is minimal.
    // We know `cafes` is non-empty, so we can initialize with the first element.
    let mut result = cafes[0];
    let mut min_last = *last_pos.get(&result).unwrap();

    for (&cafe, &pos) in last_pos.iter() {
        if pos < min_last {
            min_last = pos;
            result = cafe;
        }
    }

    result
}

